"""The real server, started as production starts it, tested over HTTP."""

import json
import subprocess
import sys
import time
import urllib.error
import urllib.request
from collections.abc import Iterator
from pathlib import Path

import pytest

ROOT = Path(__file__).resolve().parents[2]


@pytest.fixture(scope="module")
def url() -> Iterator[str]:
    process = subprocess.Popen(
        [sys.executable, "-m", "tictactoe", "--port", "0"],
        cwd=ROOT,
        stdout=subprocess.PIPE,
        text=True,
    )
    try:
        assert process.stdout is not None
        base = process.stdout.readline().split(" on ", 1)[1].strip().rstrip("/")
        deadline = time.monotonic() + 5
        while True:
            try:
                urllib.request.urlopen(f"{base}/health", timeout=1).close()
                break
            except OSError:
                if time.monotonic() > deadline:
                    raise
                time.sleep(0.05)
        yield base
    finally:
        process.terminate()
        process.wait(timeout=5)


def get(url: str) -> tuple[int, str, str]:
    try:
        with urllib.request.urlopen(url, timeout=2) as response:
            return response.status, response.headers["Content-Type"], response.read().decode()
    except urllib.error.HTTPError as error:
        return error.code, error.headers["Content-Type"], error.read().decode()


def post(url: str, body: object) -> tuple[int, dict]:
    data = json.dumps(body).encode()
    request = urllib.request.Request(url, data, {"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(request, timeout=2) as response:
            return response.status, json.load(response)
    except urllib.error.HTTPError as error:
        return error.code, json.load(error)


def test_health(url: str) -> None:
    assert get(f"{url}/health")[::2] == (200, "ok")


@pytest.mark.parametrize(
    ("path", "content_type"),
    [("/", "text/html"), ("/static/style.css", "text/css"), ("/static/app.js", "text/javascript")],
)
def test_page_and_assets(url: str, path: str, content_type: str) -> None:
    status, kind, _ = get(url + path)
    assert status == 200
    assert kind.startswith(content_type)


@pytest.mark.parametrize("path", ["/nope", "/static/../server.py", "/static/%2e%2e/game.py"])
def test_nothing_else_is_served(url: str, path: str) -> None:
    assert get(url + path)[0] == 404


def test_a_whole_game_against_hard_ends_without_a_win_for_x(url: str) -> None:
    board, status = [""] * 9, "playing"
    while status == "playing":
        cell = board.index("")
        code, answer = post(f"{url}/api/move", {"board": board, "cell": cell, "level": "hard"})
        assert code == 200
        board, status = answer["board"], answer["status"]
    assert answer["winner"] != "X"


def test_a_whole_game_between_friends(url: str) -> None:
    board = [""] * 9
    for cell in (0, 3, 1, 4, 2):
        code, answer = post(f"{url}/api/move", {"board": board, "cell": cell, "mode": "friend"})
        assert code == 200
        board = answer["board"]
    assert (answer["status"], answer["winner"], answer["line"]) == ("won", "X", [0, 1, 2])


def test_bad_moves_are_400s(url: str) -> None:
    code, answer = post(f"{url}/api/move", {"board": [""] * 9, "cell": 42})
    assert code == 400
    assert "cell" in answer["error"]


def test_oversized_bodies_are_refused(url: str) -> None:
    code, _ = post(f"{url}/api/move", {"padding": "x" * 5000})
    assert code == 413

"""HTTP server: the page, its assets, and the JSON move API.

The server keeps no state between requests. The browser sends the whole
board with every move, the server checks it, plays the move (and the
computer's reply) and sends back the new board and where the game stands.
"""

import json
from http import HTTPStatus
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path

from . import ai, game, signing

STATIC = Path(__file__).parent / "static"
# Only these files are served: a fixed map, so no path from a request ever
# reaches the file system.
ASSETS = {
    "/": ("index.html", "text/html; charset=utf-8"),
    "/static/style.css": ("style.css", "text/css; charset=utf-8"),
    "/static/app.js": ("app.js", "text/javascript; charset=utf-8"),
}
MODES = ("computer", "friend")
MAX_BODY = 1024


def handle_move(request: object) -> dict:
    """Answer one POST /api/move body. Raises IllegalMoveError on bad input."""
    if not isinstance(request, dict):
        raise game.IllegalMoveError("the body must be a JSON object")
    # A field sent as null counts as not sent.
    token = request.get("game")
    stolen = request.get("steal")
    # Without a token or a steal, exactly today's checks in today's order.
    judged = token is not None or stolen is not None
    if judged:
        board = game.check_cells(request.get("board"))
    else:
        board = game.validate(request.get("board"))
    mode = request.get("mode", "computer")
    if mode not in MODES:
        raise game.IllegalMoveError(f"mode must be one of: {', '.join(MODES)}")
    level = request.get("level", "hard")
    if mode == "computer":
        if level not in ai.LEVELS:
            raise game.IllegalMoveError(f"level must be one of: {', '.join(ai.LEVELS)}")
        if not judged and game.turn(board) != "X":
            raise game.IllegalMoveError("against the computer you play X")
    steals = signing.verify(token, board, level) if token is not None else 0
    if judged:
        board = check_steal_request(request, board, mode, steals)
    # A token proves a chain of positions from an empty board: hand out a
    # first one only when this request starts a new game.
    chained = token is not None or not any(board)
    if stolen is not None:
        board = game.steal(board, stolen, steals)
        steals = 1
    else:
        board = game.play(board, request.get("cell"), steals)
    computer_move = None
    if mode == "computer" and game.outcome(board).status == "playing":
        computer_move = ai.choose_move(board, level, steals=steals)
        board = game.play(board, computer_move, steals)
    answer = describe(board, steals) | {"computer_move": computer_move}
    new_token = None
    if mode == "computer" and answer["status"] == "playing" and chained:
        new_token = signing.sign(board, level, steals)
    can_steal = new_token is not None and steals == 0 and answer["turn"] == "X"
    return answer | {
        "game": new_token,
        "stealable": [i for i, cell in enumerate(board) if cell == "O"] if can_steal else [],
        "steal_used": steals == 1,
        "assisted": answer["winner"] == "X" and steals == 1,
    }


def check_steal_request(request: dict, board: list[str], mode: str, steals: int) -> list[str]:
    """The checks for a request with a token or a steal, after the token's."""
    stolen = request.get("steal")
    if stolen is not None:
        if request.get("cell") is not None:
            raise game.IllegalMoveError("send either cell or steal, not both")
        if mode == "friend":
            raise game.IllegalMoveError("you can only steal from the computer")
        if request.get("game") is None:
            raise game.IllegalMoveError("a steal needs the game token from the last answer")
    board = game.validate(board, steals)
    if mode == "computer" and game.turn(board, steals) != "X":
        raise game.IllegalMoveError("against the computer you play X")
    return board


def describe(board: list[str], steals: int = 0) -> dict:
    result = game.outcome(board)
    return {
        "board": board,
        "status": result.status,
        "winner": result.winner,
        "line": list(result.line) if result.line else None,
        "turn": game.turn(board, steals) if result.status == "playing" else None,
    }


class Handler(BaseHTTPRequestHandler):
    server_version = "tictactoe"

    def do_GET(self) -> None:
        self.serve(head=False)

    def do_HEAD(self) -> None:
        self.serve(head=True)

    def do_POST(self) -> None:
        if self.path != "/api/move":
            self.reply_json(HTTPStatus.NOT_FOUND, {"error": "not found"})
            return
        length = self.headers.get("Content-Length", "")
        if not length.isdigit():
            self.reply_json(HTTPStatus.LENGTH_REQUIRED, {"error": "Content-Length required"})
            return
        if int(length) > MAX_BODY:
            self.reply_json(HTTPStatus.REQUEST_ENTITY_TOO_LARGE, {"error": "body too large"})
            return
        try:
            request = json.loads(self.rfile.read(int(length)) or b"null")
            answer = handle_move(request)
        except (ValueError, game.IllegalMoveError) as error:
            # json.JSONDecodeError and IllegalMoveError are both ValueErrors
            self.reply_json(HTTPStatus.BAD_REQUEST, {"error": str(error)})
            return
        self.reply_json(HTTPStatus.OK, answer)
        if request.get("steal") is not None:
            # Only a steal that was played gets here, so level and cell are
            # known-good values. Never log the token, the key or the board.
            self.log_message(
                "steal level=%s cell=%d status=%s assisted=%s",
                request.get("level", "hard"),
                request["steal"],
                answer["status"],
                "true" if answer["assisted"] else "false",
            )

    def serve(self, *, head: bool) -> None:
        path = self.path.split("?", 1)[0]
        if path == "/health":
            self.reply(HTTPStatus.OK, b"ok", "text/plain; charset=utf-8", head=head)
        elif path in ASSETS:
            name, content_type = ASSETS[path]
            self.reply(HTTPStatus.OK, (STATIC / name).read_bytes(), content_type, head=head)
        elif path == "/api/move":
            self.send_response(HTTPStatus.METHOD_NOT_ALLOWED)
            self.send_header("Allow", "POST")
            self.send_header("Content-Length", "0")
            self.end_headers()
        else:
            self.reply(HTTPStatus.NOT_FOUND, b"not found", "text/plain; charset=utf-8", head=head)

    def reply_json(self, status: HTTPStatus, body: dict) -> None:
        self.reply(status, json.dumps(body).encode(), "application/json")

    def reply(
        self, status: HTTPStatus, body: bytes, content_type: str, *, head: bool = False
    ) -> None:
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.send_header("Cache-Control", "no-cache")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.end_headers()
        if not head:
            self.wfile.write(body)


def make_server(host: str, port: int) -> ThreadingHTTPServer:
    return ThreadingHTTPServer((host, port), Handler)

"""The rules of tic-tac-toe.

A board is a list of 9 cells, row by row, each "X", "O" or "" (empty).
X always moves first, so whose turn it is follows from the board itself.
"""

from dataclasses import dataclass

EMPTY = ""
SIZE = 9
MARKS = ("X", "O")
LINES = (
    (0, 1, 2),
    (3, 4, 5),
    (6, 7, 8),
    (0, 3, 6),
    (1, 4, 7),
    (2, 5, 8),
    (0, 4, 8),
    (2, 4, 6),
)


class IllegalMoveError(ValueError):
    """A move or a board that the rules do not allow."""


@dataclass(frozen=True)
class Outcome:
    """Where a game stands: "playing", "won" or "draw"."""

    status: str
    winner: str | None = None
    line: tuple[int, int, int] | None = None


def new_board() -> list[str]:
    return [EMPTY] * SIZE


def winning_line(board: list[str]) -> tuple[str, tuple[int, int, int]] | None:
    for line in LINES:
        a, b, c = (board[i] for i in line)
        if a and a == b == c:
            return a, line
    return None


def outcome(board: list[str]) -> Outcome:
    if found := winning_line(board):
        return Outcome("won", found[0], found[1])
    if all(board):
        return Outcome("draw")
    return Outcome("playing")


def turn(board: list[str], steals: int = 0) -> str:
    """The mark that moves next, with `steals` steals used in the game.

    A steal turns an O into an X without adding a mark, so X is to move when
    X count - O count equals `steals`.
    """
    return "X" if board.count("X") - board.count("O") == steals else "O"


def legal_moves(board: list[str]) -> list[int]:
    if outcome(board).status != "playing":
        return []
    return [i for i, cell in enumerate(board) if not cell]


def check_cells(board: object) -> list[str]:
    """Check only the shape and the cells of a board from outside, not the counts."""
    if not isinstance(board, list) or len(board) != SIZE:
        raise IllegalMoveError("board must be a list of 9 cells")
    if any(cell not in (*MARKS, EMPTY) for cell in board):
        raise IllegalMoveError('cells must be "X", "O" or ""')
    return list(board)


def validate(board: object, steals: int = 0) -> list[str]:
    """Check a board that came from outside and return it as a clean list."""
    board = check_cells(board)
    x, o = board.count("X"), board.count("O")
    if x - o not in (steals, steals + 1):
        raise IllegalMoveError("X moves first and the players alternate")
    return board


def play(board: list[str], cell: object, steals: int = 0) -> list[str]:
    """The board after the player to move takes `cell`. Does not change `board`."""
    # bool is a subclass of int, but true is not a square
    if not isinstance(cell, int) or isinstance(cell, bool) or not 0 <= cell < SIZE:
        raise IllegalMoveError("cell must be a whole number from 0 to 8")
    if outcome(board).status != "playing":
        raise IllegalMoveError("the game is over")
    if board[cell]:
        raise IllegalMoveError("that square is taken")
    after = list(board)
    after[cell] = turn(board, steals)
    return after


def steal(board: list[str], cell: object, steals: int) -> list[str]:
    """The board after X takes the computer's O on `cell`. Does not change `board`.

    A steal is X's move, allowed once per game: `steals` is how many steals
    the game has used so far.
    """
    if steals >= 1:
        raise IllegalMoveError("you have already stolen a square in this game")
    # bool is a subclass of int, but true is not a square
    if not isinstance(cell, int) or isinstance(cell, bool) or not 0 <= cell < SIZE:
        raise IllegalMoveError("steal must be a whole number from 0 to 8")
    if outcome(board).status != "playing":
        raise IllegalMoveError("the game is over")
    if turn(board, steals) != "X":
        raise IllegalMoveError("against the computer you play X")
    if board[cell] != "O":
        raise IllegalMoveError("you can only steal one of the computer's squares")
    after = list(board)
    after[cell] = "X"
    return after

